    "chapter": 4,
    "chapterQuestionNumber": 154,
    "question": "A client suspected of having Alzheimer’s disease is evaluated using the Mini-Mental State Examination. At the beginning of the evaluation, the examiner names three objects. Later in the evaluation, he asks the client to name the same three objects. The examiner is testing the client’s:",
