    "questionNumber": 910,
    "chapter": 4,
    "chapterQuestionNumber": 160,
    "question": "The nurse is caring for a client with bulimia nervosa. The nurse recog- nizes that the major difference in the client with anorexia nervosa and the client with bulimia nervosa is the client with bulimia:",
